export const rezeptById = (id: string) => rezepte.find((r) => r.id === id);

/**
 * Allergene eines Rezepts: bevorzugt die importierten, authoritativen Werte (`allergeneErfasst`);
 * nur wenn diese fehlen (z. B. bei künftig manuell im Admin angelegten Rezepten), werden sie live
 * aus den Zutaten ermittelt.
 */
export const rezeptAllergene = (r: Rezept): string[] => {
  if (r.allergeneErfasst) return r.allergeneErfasst;
  const set = new Set<string>();
  r.zutaten.forEach((rz) => zutatById(rz.zutatId)?.allergene.forEach((a) => set.add(a)));
  return [...set];
};
